ALTER TABLE "ticket_orders" ADD COLUMN "resolution_note" text;--> statement-breakpoint
ALTER TABLE "ticket_orders" ADD COLUMN "resolved_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "ticket_orders" ADD COLUMN "resolved_by" text;--> statement-breakpoint
CREATE UNIQUE INDEX "ticket_order_buyer_pair_unique" ON "ticket_orders" USING btree ("id","buyer_id");--> statement-breakpoint
ALTER TABLE "admission_tickets" ADD CONSTRAINT "ticket_buyer_ownership_fk" FOREIGN KEY ("order_id","owner_id") REFERENCES "public"."ticket_orders"("id","buyer_id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "admission_tickets" ADD CONSTRAINT "ticket_code_format" CHECK ("admission_tickets"."code" ~ '^[A-HJ-NP-Z2-9]{20}$');--> statement-breakpoint
ALTER TABLE "admission_tickets" ADD CONSTRAINT "ticket_validity_values" CHECK ("admission_tickets"."validity" in ('valid', 'revoked') and "admission_tickets"."category" in ('normal', 'vip') and "admission_tickets"."accepted_count" >= 0 and "admission_tickets"."credential_version" >= 1 and "admission_tickets"."ordinal" >= 1);--> statement-breakpoint
ALTER TABLE "ticket_orders" ADD CONSTRAINT "ticket_order_snapshot_shape" CHECK ("ticket_orders"."snapshot"->>'currency' = 'VND' and ("ticket_orders"."snapshot"->>'totalPrice')::integer > 0 and (("ticket_orders"."snapshot"->>'packageName' = 'Silver' and "ticket_orders"."snapshot"->>'category' = 'normal' and ("ticket_orders"."snapshot"->>'quantity')::integer = 1) or ("ticket_orders"."snapshot"->>'packageName' = 'Golden' and "ticket_orders"."snapshot"->>'category' = 'normal' and ("ticket_orders"."snapshot"->>'quantity')::integer = 2) or ("ticket_orders"."snapshot"->>'packageName' = 'Platinum' and "ticket_orders"."snapshot"->>'category' = 'normal' and ("ticket_orders"."snapshot"->>'quantity')::integer = 3) or ("ticket_orders"."snapshot"->>'packageName' = 'VIP' and "ticket_orders"."snapshot"->>'category' = 'vip' and ("ticket_orders"."snapshot"->>'quantity')::integer = 1)));